"use client";

/**
 * Wordmark build: solid blocks slide in and stack into a line, then resolve
 * letter by letter into the brand name. One accent block stays behind as the
 * full stop.
 *
 * Written by Better Design. Each block takes the width of its own letter, so
 * the bar of blocks is the exact shape of the word it becomes.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, type SoundCue, SoundTrack, springs, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["800"], subsets: ["latin"] });

const FONT_SIZE = 220;
/** Frames between one block's arrival and the next. */
const ARRIVE_GAP = 4;
const RESOLVE_AT = 56;
const RESOLVE_GAP = 2.5;
const RESOLVE_FRAMES = 14;

/**
 * The sound of a WordmarkBuild: a quiet pop for each block that snaps into
 * the bar, a riser that peaks as the letters resolve, the logo hit on that
 * frame, and a shimmer as the full stop settles.
 */
export function wordmarkBuildCues(name = "Your brand"): SoundCue[] {
  const blocks = Array.from(name).filter((char) => char.trim() !== "").length;
  const cues: SoundCue[] = Array.from({ length: blocks }, (_, n) => ({
    sfx: n % 2 === 0 ? "pop-soft" : "pop",
    at: 4 + n * ARRIVE_GAP + 3,
    gain: -6 - (4 * n) / Math.max(1, blocks - 1),
  }));
  cues.push({ sfx: "riser", at: RESOLVE_AT }, { sfx: "logo-hit", at: RESOLVE_AT }, { sfx: "shimmer", at: RESOLVE_AT + blocks * RESOLVE_GAP + 10, gain: -5 });
  return cues;
}

export interface WordmarkBuildProps {
  /** The brand name the blocks resolve into. */
  name?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
  /** Play the shot's own sound cues. Leave off inside a film that plays every scene's cues in one SoundTrack. */
  sound?: boolean;
}

/** Blocks slide, stack and resolve into the brand name, ending on an accent full stop. */
export function WordmarkBuild({ name = "Your brand", theme: themeOverride, font, sound = false }: WordmarkBuildProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  const chars = Array.from(name);

  let order = 0;
  const cells = chars.map((char, i) => {
    if (char.trim() === "") {
      return <span key={i} style={{ display: "inline-block", width: "0.26em" }} />;
    }
    const n = order++;
    const arrive = spring({ frame: frame - (4 + n * ARRIVE_GAP), fps, config: springs.snappy });
    const from = n % 2 === 0 ? -1 : 1;
    const resolve = easings.out(progress(frame, RESOLVE_AT + n * RESOLVE_GAP, RESOLVE_FRAMES));
    return (
      <span key={i} style={{ position: "relative", display: "inline-block" }}>
        <span
          style={{
            position: "absolute",
            left: "0.015em",
            right: "0.015em",
            top: "0.2em",
            bottom: "0.12em",
            borderRadius: "0.035em",
            background: theme.foreground,
            opacity: arrive > 0.01 ? 1 - resolve * resolve : 0,
            transformOrigin: "50% 100%",
            transform: `translateY(${from * (1 - arrive) * 520}px) scaleY(${1 - resolve})`,
          }}
        />
        <span style={{ display: "inline-block", opacity: resolve, transform: `translateY(${(1 - resolve) * 0.12}em)` }}>{char}</span>
      </span>
    );
  });

  const accentAt = 4 + order * ARRIVE_GAP + 4;
  const accentIn = spring({ frame: frame - accentAt, fps, config: springs.bouncy });
  const dotAt = RESOLVE_AT + order * RESOLVE_GAP + 6;
  const dot = easings.inOut(progress(frame, dotAt, 16));
  const accentW = 0.42 - (0.42 - 0.17) * dot;
  const accentH = 0.72 - (0.72 - 0.17) * dot;
  const settle = easings.out(progress(frame, 0, 120));

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      {sound ? <SoundTrack cues={wordmarkBuildCues(name)} music={false} /> : null}
      <AbsoluteFill style={{ background: `radial-gradient(ellipse 1100px 520px at 50% 52%, ${withAlpha(theme.primary, 0.06)}, ${withAlpha(theme.primary, 0)} 70%)` }} />
      <div
        style={{
          whiteSpace: "nowrap",
          fontSize: FONT_SIZE,
          fontWeight: 800,
          letterSpacing: "-0.05em",
          lineHeight: 1,
          color: theme.foreground,
          transform: `scale(${0.96 + 0.04 * settle})`,
        }}
      >
        {cells}
        <span style={{ position: "relative", display: "inline-block", width: `${accentW + 0.06}em`, height: "1em", verticalAlign: "top", marginLeft: "0.02em" }}>
          <span
            style={{
              position: "absolute",
              left: "0.02em",
              bottom: "0.125em",
              width: `${accentW}em`,
              height: `${accentH}em`,
              borderRadius: "0.035em",
              background: theme.primary,
              opacity: accentIn > 0.01 ? 1 : 0,
              transform: `translateY(${(1 - accentIn) * -560}px)`,
            }}
          />
        </span>
      </div>
    </AbsoluteFill>
  );
}
